import {fs} from './gta-email-recovery-runtime.mjs';
import {parseEnv} from 'node:util';
import {randomUUID} from 'node:crypto';
const {db}=await import('./reply-runtime-20261007.mjs');
const file='artifacts/gta-subcontractor-recruiting-20261014/4uj-owner-call-followup.json';
if(fs.existsSync(file))throw Error('Prior reservation exists; no blind resend');
const from='+14374650584',to='+16478006624';
const [c]=await db('subcontractors',{phone:'eq.'+to});
if(!c||c.status==='blocked')throw Error('Missing or blocked contractor');
const thread=await db('sms_messages',{from_number:'eq.'+to,direction:'eq.inbound',order:'created_at.desc',limit:'100'});
if(thread.some(r=>/^(stop|unsubscribe)\b/i.test(r.body.trim())))throw Error('Opted out');
const body="Hi, John from Saturn Star Movers here. I just tried calling but reached voicemail. When would be the best time to give you a call to discuss working together? Happy to work around your schedule.";
const receipt={from,to,body,state:'reserved_no_retry',contractor_id:c.id,at:new Date().toISOString()};fs.writeFileSync(file,JSON.stringify(receipt,null,2),{flag:'wx'});
const key=parseEnv(fs.readFileSync('.env.local','utf8')).TELNYX_API_KEY;
const r=await fetch('https://api.telnyx.com/v2/messages',{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({from,to,text:body,webhook_url:'https://go.quote2move.com/api/sales/telnyx/messaging',use_profile_webhooks:true}),signal:AbortSignal.timeout(25000)});
const result=await r.json();Object.assign(receipt,{result,state:r.ok?'provider_accepted':'provider_rejected'});fs.writeFileSync(file,JSON.stringify(receipt,null,2));
if(!r.ok||!result.data?.id)throw Error('Not confirmed; reconcile before retry');
const sid='telnyx:'+result.data.id;
const [sms]=await db('sms_messages',{},'POST',{id:randomUUID(),from_number:from,to_number:to,body,direction:'outbound',lead_id:null,twilio_sid:sid,created_at:new Date().toISOString()});
const check=await db('sms_messages',{twilio_sid:'eq.'+sid,select:'id'});if(check.length!==1)throw Error('CRM receipt mismatch');
await db('subcontractors',{id:'eq.'+c.id},'PATCH',{notes:(c.notes||'')+'\nOwner reported calling October 14 and reaching voicemail. Sent contextual SMS asking best call time. Earlier response: interested in future partnership, booked October 15. No call appointment confirmed.',updated_at:new Date().toISOString()});
Object.assign(receipt,{state:'accepted_crm_verified',sms_id:sms.id});fs.writeFileSync(file,JSON.stringify(receipt,null,2));console.log(JSON.stringify({business:c.company_name,state:receipt.state}));
